/bin/bash -lc "cat > /tmp/check-small-universe.cjs <<'JS'
const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const elements = new Map();
const context2d = new Proxy({}, { get: (_, key) => key === 'createRadialGradient' ? () => ({ addColorStop() {} }) : () => {} });
function element(selector) {
  if ("'!elements.has(selector)) elements.set(selector, {
    textContent: '"'', value: '', handlers: {}, attributes: {},
    addEventListener(type, fn) { this.handlers[type] = fn; },
    setAttribute(key, value) { this.attributes[key] = value; },
    getBoundingClientRect() { return { width: 1200, height: 850, left: 0, top: 0 }; },
    getContext() { return context2d; }, setPointerCapture() {}, releasePointerCapture() {},
  });
  return elements.get(selector);
}
function setup(reducedMotion) {
  elements.clear();
  const sandbox = { console, Math, setTimeout: () => 1, clearTimeout() {}, devicePixelRatio: 2,
    matchMedia: () => ({ matches: reducedMotion }), requestAnimationFrame() {},
    ResizeObserver: class { observe() {} },
    document: { querySelector: element, addEventListener() {}, hidden: false },
  };
  vm.createContext(sandbox);
  vm.runInContext(fs.readFileSync('/tmp/small-universe-check.js', 'utf8'), sandbox);
  return expression => vm.runInContext(expression, sandbox);
}
const run = setup(false);
assert.equal(run('bodies.length'), 3);
assert.equal(run('paused'), false);
const initialEnergy = run('bodies.map(b => (b.vx*b.vx+b.vy*b.vy)/2-MU/Math.hypot(b.x,b.y))');
run('for(let i=0;i<36000;i++) tick()');
assert.equal(run('bodies.length'), 3, 'seeded orbits survive 600 simulation seconds');
const finalEnergy = run('bodies.map(b => (b.vx*b.vx+b.vy*b.vy)/2-MU/Math.hypot(b.x,b.y))');
initialEnergy.forEach((energy, i) => assert.ok(Math.abs((finalEnergy[i] - energy) / energy) < 0.00001, 'orbital energy remains stable'));
assert.ok(run('bodies.every(b => b.trail.length <= 430)'), 'trail memory is bounded');
run('draw()');
element('#pause').handlers.click();
assert.equal(run('paused'), true);
assert.equal(element('#pause').textContent, 'Play');
element('#add').handlers.click();
assert.equal(run('bodies.length'), 4);
run('for(let i=0;i<30;i++) addBody(200, 0, 0, 10)');
assert.equal(run('bodies.length'), 16);
assert.equal(element('#count').textContent, 16);
element('#reset').handlers.click();
assert.equal(run('bodies.length'), 3);
const sky = element('#sky');
const location = run('({clientX:center.x+150*scale,clientY:center.y})');
const event = { ...location, pointerId: 1, isPrimary: true, button: 0 };
sky.handlers.pointerdown(event);
run('draw()');
sky.handlers.pointerup(event);
assert.equal(run('bodies.length'), 4);
assert.ok(run('Math.abs(bodies[3].vy-Math.sqrt(MU/150)) < 1e-9'), 'tap creates a circular orbit');
sky.handlers.pointerdown(event);
sky.handlers.pointermove({ ...event, clientX: event.clientX - 80 });
assert.ok(run('launchVelocity().vx > 0'), 'pulling left launches right');
sky.handlers.pointercancel();
assert.equal(run('drag'), null);
run('bodies=[]; addBody(5,0,0,0); tick()');
assert.equal(run('bodies.length'), 0, 'star absorbs comet');
run('addBody(1900,0,0,0); tick()');
assert.equal(run('bodies.length'), 0, 'faraway comet is removed');
const reduced = setup(true);
assert.equal(reduced('paused'), true);
assert.equal(element('#pause').textContent, 'Play');
console.log('Passed: stable orbits, bounded trails and comet count, rendering calls, pause/reset/add, tap and drag launch, cancellation, absorption, escape, reduced-motion startup.');
